def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d_total = 0
    my_d_total = 0
    for me_act, opp_act in history:
        if me_act == 'D':
            my_d_total += 1
        if opp_act == 'D':
            opp_d_total += 1

    w = min(12, n)
    opp_d_recent = 0
    my_d_recent = 0
    for i in range(n - w, n):
        me_act, opp_act = history[i]
        if me_act == 'D':
            my_d_recent += 1
        if opp_act == 'D':
            opp_d_recent += 1

    opp_d_streak = 0
    if last_opp == 'D':
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                opp_d_streak += 1
            else:
                break

    mutual_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_d_streak += 1
        else:
            break

    prev_opp_c_streak = 0
    if last_opp == 'D':
        for i in range(n - 2, -1, -1):
            if history[i][1] == 'C':
                prev_opp_c_streak += 1
            else:
                break

    mutual_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            mutual_c_streak += 1
        else:
            break

    tolerated_after_my_d = 0
    punished_after_my_d = 0
    start = max(1, n - 16)
    for i in range(start, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                tolerated_after_my_d += 1
            else:
                punished_after_my_d += 1

    confirmed_tolerant = 0
    start = max(0, n - 20)
    for i in range(start, n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i + 1][1] == 'C':
            confirmed_tolerant += 1

    if opp_d_total == n:
        return 'D'
    if opp_d_streak >= 3:
        return 'D'
    if opp_d_recent >= 5:
        return 'D'

    hostile = (
        opp_d_recent >= 4
        or opp_d_total * 2 > n
        or (punished_after_my_d >= 3 and tolerated_after_my_d < punished_after_my_d + 2)
    )

    max_exploit_defects = max(3, n // 10)

    if last_opp == 'C' and not hostile:
        if opp_d_total <= max_exploit_defects and opp_d_recent <= 2:
            if confirmed_tolerant >= 1:
                return 'D'
            if opp_d_total == 0 and opp_d_recent == 0 and my_d_total >= 2:
                return 'D'

        if (
            opp_d_recent <= 2
            and my_d_total >= 3
            and tolerated_after_my_d >= 3
            and punished_after_my_d <= 1
        ):
            return 'D'

    if (
        last_opp == 'C'
        and not hostile
        and opp_d_total == 0
        and my_d_total == 0
        and mutual_c_streak >= 16
        and n <= 85
    ):
        if n >= 20 or rng.random() < 0.1:
            return 'D'

    if (
        last_opp == 'C'
        and not hostile
        and confirmed_tolerant == 0
        and opp_d_total * 5 < n
        and opp_d_total <= 2
        and my_d_total <= 3
        and mutual_c_streak >= 30
        and 30 <= n <= 80
        and rng.random() < 0.03
    ):
        return 'D'

    if last_opp == 'D':
        if mutual_d_streak >= 2 and opp_d_recent <= 4 and opp_d_total <= max(6, n // 4):
            return 'C' if rng.random() < 0.65 else 'D'

        if opp_d_total <= 1 and prev_opp_c_streak >= 6:
            return 'C'

        if opp_d_total <= 2 and opp_d_recent <= 1 and prev_opp_c_streak >= 8:
            return 'C'

        if last_me == 'D' and opp_d_total <= max(4, n // 8) and opp_d_recent <= 2:
            if rng.random() < 0.55:
                return 'C'

        if opp_d_recent >= 3 or opp_d_total * 2 > n or opp_d_streak >= 2:
            return 'D'

        if opp_d_recent >= 2:
            return 'D' if rng.random() < 0.75 else 'C'

        return 'D' if rng.random() < 0.55 else 'C'

    if opp_d_total > 2 and opp_d_recent >= 3:
        return 'D' if rng.random() < 0.45 else 'C'

    if opp_d_total * 3 > n and opp_d_recent >= 2:
        return 'D' if rng.random() < 0.35 else 'C'

    return 'C'
